class Solution {
    public int minimumSwap(String s1,String s2){
        int xy=0,yx=0;
        for(int i=0;i<s1.length();i++)if(s1.charAt(i)!=s2.charAt(i)){
            if(s1.charAt(i)=='x')xy++;
            else yx++;
        }
        if((xy+yx)%2==1)return -1;
        return xy/2+yx/2+(xy%2)*2;
    }
}

code.kotlin:
class Solution {
    fun minimumSwap(s1:String,s2:String):Int{
        var xy=0;
        var yx=0;
        for(i in s1.indices)if(s1[i]!=s2[i]){
            if(s1[i]=='x')xy++ else yx++
        };
        if((xy+yx)%2==1)return -1;
        return xy/2+yx/2+xy%2*2
    }
}

